CREATE TABLE app_private.tool_key_settings (
    workspace_id uuid NOT NULL,
    provider text NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    value text,
    CONSTRAINT tool_key_settings_provider_check CHECK ((provider = ANY (ARRAY['tavily'::text, 'jina'::text, 'serpapi'::text, 'github_token'::text, 'github_repository'::text, 'browser_executor'::text]))),
    CONSTRAINT tool_key_settings_value_check CHECK (((value IS NULL) OR ((provider = 'github_repository'::text) AND (value ~ '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$'::text)) OR ((provider = 'browser_executor'::text) AND (value = ANY (ARRAY['enabled'::text, 'disabled'::text]))))),
    CONSTRAINT tool_key_settings_version_check CHECK ((version >= 0))
);

--
-- Name: tool_receipts; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.tool_receipts (
    operation_id text NOT NULL,
    run_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    tool_id text NOT NULL,
    tool_version integer NOT NULL,
    argument_hash text NOT NULL,
    status text NOT NULL,
    result jsonb,
    generation bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    can_readback boolean DEFAULT false NOT NULL,
    evidence text,
    reconciled_by uuid,
    reconciled_at timestamp with time zone,
    failure_code text,
    failure_detail text,
    CONSTRAINT tool_receipts_status_check CHECK ((status = ANY (ARRAY['started'::text, 'succeeded'::text, 'failed'::text, 'unknown'::text]))),
    CONSTRAINT tool_receipts_tool_version_check CHECK ((tool_version >= 1))
);

--
-- Name: tool_switches; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.tool_switches (
    workspace_id uuid NOT NULL,
    kind text NOT NULL,
    target text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tool_switches_kind_check CHECK ((kind = ANY (ARRAY['tool'::text, 'group'::text]))),
    CONSTRAINT tool_switches_target_check CHECK ((target ~ '^[a-z][a-z0-9_]{2,63}$'::text)),
    CONSTRAINT tool_switches_version_check CHECK ((version >= 1))
);

--
-- Name: tool_uses; Type: TABLE; Schema: app_private; Owner: -
--

CREATE TABLE app_private.tool_uses (
    id bigint NOT NULL,
    run_id uuid NOT NULL,
    root_run_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    sequence_in_run integer NOT NULL,
    tool_id text NOT NULL,
    tool_version integer,
    tool_group text,
    provider text,
    cost_class text,
    plan_version integer,
    task_id text,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    finished_at timestamp with time zone,
    outcome text,
    code text,
    input_digest text NOT NULL,
    input_public jsonb DEFAULT '{}'::jsonb NOT NULL,
    output_public jsonb,
    output_bytes integer,
    operation_id text,
    provider_units numeric,
    metered boolean DEFAULT false NOT NULL,
    generation bigint NOT NULL,
    instance_key text,
    CONSTRAINT tool_uses_check CHECK (((outcome IS NULL) = (finished_at IS NULL))),
    CONSTRAINT tool_uses_input_public_check CHECK ((jsonb_typeof(input_public) = 'object'::text)),
    CONSTRAINT tool_uses_instance_key_check CHECK (((instance_key IS NULL) OR ((char_length(instance_key) >= 1) AND (char_length(instance_key) <= 200)))),
    CONSTRAINT tool_uses_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'failed'::text, 'unknown'::text, 'denied'::text]))),
    CONSTRAINT tool_uses_output_bytes_check CHECK ((output_bytes >= 0)),
    CONSTRAINT tool_uses_output_public_check CHECK (((output_public IS NULL) OR (jsonb_typeof(output_public) = 'object'::text))),
    CONSTRAINT tool_uses_sequence_in_run_check CHECK ((sequence_in_run >= 1)),
    CONSTRAINT tool_uses_tool_id_check CHECK (((char_length(tool_id) >= 1) AND (char_length(tool_id) <= 100))),
    CONSTRAINT tool_uses_tool_version_check CHECK ((tool_version >= 1))
);

--
-- Name: tool_uses_id_seq; Type: SEQUENCE; Schema: app_private; Owner: -
--

ALTER TABLE app_private.tool_uses ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME app_private.tool_uses_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

