    CONSTRAINT workspace_retention_check CHECK (((run_days IS NULL) OR (receipt_days IS NULL) OR (receipt_days >= run_days))),
    CONSTRAINT workspace_retention_keys_need_content CHECK (((receipt_days IS NULL) OR (run_days IS NOT NULL))),
    CONSTRAINT workspace_retention_receipt_days_check CHECK ((receipt_days >= 1)),
    CONSTRAINT workspace_retention_run_days_check CHECK ((run_days >= 1))
);

