-- Name: approval_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_requests (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    run_id uuid NOT NULL,
    operation_id text NOT NULL,
    tool_id text NOT NULL,
    tool_version integer NOT NULL,
    operation_class text NOT NULL,
    argument_hash text NOT NULL,
    arguments jsonb NOT NULL,
    scope_hash text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    policy_reason text,
    resource_target text,
    requested_by uuid,
    requested_by_agent jsonb,
    scope_snapshot jsonb,
    policy_version text,
    policy_rule text,
    review_detail jsonb,
    consumed_at timestamp with time zone,
    CONSTRAINT approval_requests_policy_rule_check CHECK (((policy_rule IS NULL) OR (policy_rule = ANY (ARRAY['consequential_external_write'::text, 'tool_marked'::text, 'action_marked'::text])))),
    CONSTRAINT approval_requests_requested_by_agent_check CHECK (((requested_by_agent IS NULL) OR ((requested_by_agent ->> 'kind'::text) = ANY (ARRAY['expert'::text, 'coordinator'::text])))),
    CONSTRAINT approval_requests_review_detail_check CHECK (((review_detail IS NULL) OR (jsonb_typeof(review_detail) = 'object'::text))),
    CONSTRAINT approval_requests_scope_snapshot_check CHECK (((scope_snapshot IS NULL) OR ((jsonb_typeof((scope_snapshot -> 'tools'::text)) = 'object'::text) AND (jsonb_typeof((scope_snapshot -> 'paths'::text)) = 'array'::text)))),
    CONSTRAINT approval_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'withdrawn'::text])))
);

